def analyze_transformations():
    inputs = ['wfe', 'gzxkc', 'zvh', 'bvzcak', 'vhc']
    outputs = ['wfe', 'gzxkc', 'zdh', 'xafaajcak', 'dhc']

    print("Input -> Output")
    for i, (inp, out) in enumerate(zip(inputs, outputs)):
        print(f"'{inp}' -> '{out}'")

    print("\nCharacter-by-character analysis:")
    for i, (inp, out) in enumerate(zip(inputs, outputs)):
        print(f"Input {i}: '{inp}'")
        print(f"Output {i}: '{out}'")
        if len(inp) == len(out):
            print("Same length")
        else:
            print(f"Different lengths: {len(inp)} -> {len(out)}")
        print()

